<?php
session_start();require '../includes/db_connect.php';if(!isset($_SESSION['logged_in'])){http_response_code(403);exit('Unauthorized');}$userId=(int)($_SESSION['role']==='Super_Admin'&&isset($_GET['user_id'])?$_GET['user_id']:$_SESSION['user_id']);if($_SESSION['role']!=='Super_Admin'&&$userId!==(int)$_SESSION['user_id']){http_response_code(403);exit('Unauthorized');}
$u=$pdo->prepare('SELECT UserID,Username,Email,FirstName,LastName,MiddleName,ExtName,Role,AccountStatus,StudentID_Num,LRN,YearLevel,GPA,Major,Department,ContactNumber,DateOfBirth,Gender,StreetBarangay,CityMunicipality,Province,Region,ZipCode,DisabilityType,IndigenousGroup FROM users WHERE UserID=?');$u->execute([$userId]);$user=$u->fetch(PDO::FETCH_ASSOC);if(!$user){http_response_code(404);exit('User not found');}
$query=function($sql)use($pdo,$userId){$s=$pdo->prepare($sql);$s->execute([$userId]);return $s->fetchAll(PDO::FETCH_ASSOC);};$data=['generated_at'=>date(DATE_ATOM),'privacy_notice'=>'RA 10173 data access and portability copy','profile'=>$user,'applications'=>$query('SELECT a.ApplicationID,s.Name Scholarship,a.DateSubmitted,a.Status,a.TotalScore,a.GPA,a.YearLevel FROM application a JOIN scholarship s ON s.ScholarshipID=a.ScholarshipID WHERE a.UserID=?'),'uploaded_documents'=>$query('SELECT d.SubmittedDocID,d.ApplicationID,r.DocumentName,d.OriginalFileName,d.MimeType,d.FileSize,d.UploadDate,d.VerificationStatus FROM submitted_document d JOIN application a ON a.ApplicationID=d.ApplicationID JOIN document_requirement r ON r.RequirementID=d.RequirementID WHERE a.UserID=?'),'vault_documents'=>$query('SELECT VaultID,DocumentType,OriginalFileName,MimeType,FileSize,FileChecksum,MalwareScanStatus,UploadDate FROM user_vault WHERE UserID=?'),'consents'=>$query('SELECT NoticeVersion,ConsentStatus,GrantedAt,WithdrawnAt FROM privacy_consents WHERE UserID=?'),'privacy_requests'=>$query('SELECT RequestID,RequestType,RequestDetails,Status,ResolutionNotes,SubmittedAt,DueAt,ResolvedAt FROM privacy_requests WHERE UserID=?')];
logAudit($pdo,(int)$_SESSION['user_id'],'Privacy Data Exported',"Data access copy generated for user #$userId.");header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="ScholarLink_Privacy_Data_'.$userId.'_'.date('Y-m-d').'.json"');echo json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
